window.SCSRC=[{"name":"Shotcaller/main.swift","text":"// Shotcaller\n//\n// Watches your screenshot folder and renames each new screenshot after what it\n// shows, so \"Screenshot 2026-09-21 at 3.45.12 PM.png\" becomes\n// \"Discord chat about Destiny lore 2026-09-21.png\". Screen recordings get the\n// same treatment, named after a frame from early in the recording.\n//\n// Two things here exist for reasons that are not obvious:\n//\n// 1. This ships as an app bundle rather than a plain background script. macOS\n//    refuses an unbundled script any access to Desktop, Documents and Downloads,\n//    and denies it silently, with no prompt and no error. A bundled app with its\n//    own identifier is allowed to ask, so the usual access box appears instead.\n//\n// 2. The looking happens in a separate helper process with a time limit. Apple's\n//    models take a minute or more to get ready the first time after an install, a\n//    macOS update or a login, and are fast after that, so Shotcaller readies them on\n//    a throwaway image at startup. Keeping the reader separate means a slow or stuck\n//    read can never stop the watcher, and the reader never needs folder permission\n//    of its own.\n//\n// Shotcaller never deletes anything. A file it cannot find a sensible title for\n// keeps the name macOS gave it.\n\nimport Foundation\n\n// MARK: - settings\n\nlet fm = FileManager.default\nlet home = fm.homeDirectoryForCurrentUser\n// A test copy can be pointed somewhere else, to leave the real settings and log alone.\nlet supportDir = ProcessInfo.processInfo.environment[\"SHOTCALLER_SUPPORT\"].map {\n    URL(fileURLWithPath: $0)\n} ?? home.appendingPathComponent(\"Library/Application Support/Shotcaller\")\nlet logFile = supportDir.appendingPathComponent(\"shotcaller.log\")\nlet configFile = supportDir.appendingPathComponent(\"config.json\")\n// Next to this executable, which is where install.sh puts it.\nlet reader = URL(fileURLWithPath: CommandLine.arguments[0]).resolvingSymlinksInPath()\n    .deletingLastPathComponent().appendingPathComponent(\"ShotcallerReader\")\n// Private scratch space for the copies the reader looks at, one per running copy of\n// Shotcaller, so two copies can never clear out each other's files.\nlet scratchRoot = fm.temporaryDirectory\nlet scratchDir = scratchRoot.appendingPathComponent(\"com.strider.shotcaller-\\(getpid())\")\n\nlet imageTypes: Set<String> = [\"png\", \"jpg\", \"jpeg\", \"heic\", \"tif\", \"tiff\", \"gif\", \"bmp\"]\nlet videoTypes: Set<String> = [\"mov\", \"mp4\"]\n\nstruct Config: Codable, Equatable {\n    /// Folder to watch. Empty means \"ask macOS where screenshots go\".\n    var watchFolder = \"\"\n    /// Keep the date in the new filename, so the folder still sorts by when.\n    var keepDate = true\n    /// Let Apple's on-device model look at the shot and write the title. When off,\n    /// or when Apple Intelligence is not available, the biggest line of text is used.\n    var useAppleIntelligence = true\n    /// Rename screen recordings too, after a frame from early in the recording.\n    var renameRecordings = true\n    /// Filename prefixes macOS uses for a fresh screenshot, per language. Only files\n    /// starting with one of these are ever touched, which is also what stops a file\n    /// Shotcaller has already renamed from being picked up a second time.\n    var prefixes: [String] = [\n        \"screenshot\", \"screen shot\",          // English\n        \"bildschirmfoto\",                     // German\n        \"captura de pantalla\",                // Spanish\n        \"capture d'écran\", \"capture d’écran\", // French\n        \"istantanea schermo\",                 // Italian\n        \"schermafbeelding\",                   // Dutch\n        \"skärmavbild\",                        // Swedish\n        \"zrzut ekranu\",                       // Polish\n        \"captura de ecrã\", \"captura de tela\", // Portuguese\n        \"снимок экрана\",                      // Russian\n        \"스크린샷\",                              // Korean\n        \"スクリーンショット\",                       // Japanese\n        \"截屏\", \"螢幕截圖\", \"截圖\"                 // Chinese\n    ]\n    /// The same for screen recordings.\n    var recordingPrefixes: [String] = [\n        \"screen recording\", \"bildschirmaufnahme\", \"grabación de pantalla\",\n        \"enregistrement de l’écran\", \"enregistrement de l'écran\", \"registrazione schermo\",\n        \"schermopname\", \"skärminspelning\", \"nagranie ekranu\", \"gravação de tela\",\n        \"gravação do ecrã\", \"запись экрана\", \"화면 기록\", \"画面収録\", \"录屏\", \"螢幕錄影\"\n    ]\n\n    init() {}\n\n    enum CodingKeys: String, CodingKey, CaseIterable {\n        case watchFolder, keepDate, useAppleIntelligence, renameRecordings, prefixes, recordingPrefixes\n    }\n\n    // Every key is optional, so a config.json from an older version, or one with a\n    // key deleted by hand, still loads and keeps the settings that are there.\n    init(from decoder: Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        let d = Config()\n        watchFolder = try c.decodeIfPresent(String.self, forKey: .watchFolder) ?? d.watchFolder\n        keepDate = try c.decodeIfPresent(Bool.self, forKey: .keepDate) ?? d.keepDate\n        useAppleIntelligence = try c.decodeIfPresent(Bool.self, forKey: .useAppleIntelligence) ?? d.useAppleIntelligence\n        renameRecordings = try c.decodeIfPresent(Bool.self, forKey: .renameRecordings) ?? d.renameRecordings\n        prefixes = Config.usable(try c.decodeIfPresent([String].self, forKey: .prefixes) ?? d.prefixes)\n        recordingPrefixes = Config.usable(\n            try c.decodeIfPresent([String].self, forKey: .recordingPrefixes) ?? d.recordingPrefixes)\n    }\n\n    /// A blank or one letter prefix would match nearly every file in the folder.\n    static func usable(_ list: [String]) -> [String] {\n        list.map { $0.trimmingCharacters(in: .whitespaces).lowercased() }.filter { $0.count >= 2 }\n    }\n}\n\nvar configStamp: Date?\nvar configBroken = false\n\n/// Reads config.json when it has changed since last time. A file with a mistake in\n/// it is never overwritten: the last good settings stay in use and the log says why.\nfunc loadConfig(_ current: Config) -> Config {\n    guard fm.fileExists(atPath: configFile.path) else {\n        save(Config())\n        return Config()\n    }\n    let stamp = (try? fm.attributesOfItem(atPath: configFile.path))?[.modificationDate] as? Date\n    if stamp != nil, stamp == configStamp { return current }\n    configStamp = stamp\n    do {\n        let data = try Data(contentsOf: configFile)\n        let parsed = try JSONDecoder().decode(Config.self, from: data)\n        if configBroken { log(\"CONFIG config.json reads fine again\"); configBroken = false }\n        // Add any settings this version knows about that the file does not show yet.\n        if let keys = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],\n           Config.CodingKeys.allCases.contains(where: { keys[$0.rawValue] == nil }) {\n            save(parsed)\n        }\n        return parsed\n    } catch {\n        if !configBroken {\n            log(\"CONFIG config.json cannot be read or has a mistake in it, so the last good settings stay in use\")\n            configBroken = true\n        }\n        return current\n    }\n}\n\nfunc save(_ config: Config) {\n    let encoder = JSONEncoder()\n    encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]\n    guard let data = try? encoder.encode(config) else { return }\n    try? data.write(to: configFile, options: .atomic)\n    try? fm.setAttributes([.posixPermissions: 0o600], ofItemAtPath: configFile.path)\n    configStamp = (try? fm.attributesOfItem(atPath: configFile.path))?[.modificationDate] as? Date\n}\n\n/// Where macOS is currently told to put screenshots. Falls back to the Desktop,\n/// which is the factory default.\nfunc screenshotFolder(_ config: Config) -> URL {\n    if !config.watchFolder.isEmpty {\n        return URL(fileURLWithPath: (config.watchFolder as NSString).expandingTildeInPath)\n    }\n    if let defaults = UserDefaults(suiteName: \"com.apple.screencapture\"),\n       let location = defaults.string(forKey: \"location\"), !location.isEmpty {\n        return URL(fileURLWithPath: (location as NSString).expandingTildeInPath)\n    }\n    return home.appendingPathComponent(\"Desktop\")\n}\n\n// MARK: - log\n\n// Fixed to the Gregorian calendar, so a Mac set to another calendar still gets\n// dates like 2026-09-21 rather than 2569-09-21.\nfunc formatter(_ format: String) -> DateFormatter {\n    let f = DateFormatter()\n    f.locale = Locale(identifier: \"en_US_POSIX\")\n    f.calendar = Calendar(identifier: .gregorian)\n    f.dateFormat = format\n    return f\n}\nlet stamp = formatter(\"yyyy-MM-dd HH:mm:ss\")\nlet dayFormat = formatter(\"yyyy-MM-dd\")\nvar linesSinceTrim = 0\n\n// Called from more than one thread, so writes take turns.\nlet logLock = NSLock()\n\nfunc log(_ message: String) {\n    logLock.lock(); defer { logLock.unlock() }\n    // A filename can hold a line break; it must not be able to forge a log line.\n    let flat = String(String.UnicodeScalarView(message.unicodeScalars.map {\n        CharacterSet.controlCharacters.contains($0) ? \" \" : $0\n    }))\n    let data = Data(\"\\(stamp.string(from: Date()))  \\(flat)\\n\".utf8)\n    if let handle = try? FileHandle(forWritingTo: logFile) {\n        _ = try? handle.seekToEnd()\n        try? handle.write(contentsOf: data)\n        try? handle.close()\n    } else {\n        // The log lists what your screenshots were about, so only you may read it.\n        fm.createFile(atPath: logFile.path, contents: data, attributes: [.posixPermissions: 0o600])\n    }\n    // Keep the log from growing without limit. Checked now and then, not every line.\n    linesSinceTrim += 1\n    guard linesSinceTrim >= 50 else { return }\n    linesSinceTrim = 0\n    if let size = try? fm.attributesOfItem(atPath: logFile.path)[.size] as? Int, size > 512_000,\n       let text = try? String(contentsOf: logFile, encoding: .utf8) {\n        let kept = text.split(separator: \"\\n\").suffix(2000).joined(separator: \"\\n\")\n        try? (kept + \"\\n\").write(to: logFile, atomically: true, encoding: .utf8)\n    }\n}\n\n// MARK: - asking the reader what the picture shows\n\nenum Reading {\n    case named(String, how: String)\n    case nothing      // the reader found nothing worth naming the file after\n    case timedOut\n    case tooBig       // too large to copy from another disk\n}\n\n/// Runs the reader with a time limit, and returns what it printed.\nfunc runReader(_ arguments: [String], limit: TimeInterval) -> (status: Int32, output: String)? {\n    let task = Process()\n    task.executableURL = reader\n    task.arguments = arguments\n    let pipe = Pipe()\n    task.standardOutput = pipe\n    task.standardError = FileHandle.nullDevice\n    do { try task.run() } catch {\n        log(\"ERROR  could not start the reader: \\(error.localizedDescription)\")\n        return (-1, \"\")\n    }\n\n    // Read while waiting, so a chatty reader can never fill the pipe and stall.\n    var output = Data()\n    let finished = DispatchSemaphore(value: 0)\n    DispatchQueue.global(qos: .utility).async {\n        output = (try? pipe.fileHandleForReading.readToEnd()) ?? Data()\n        task.waitUntilExit()\n        finished.signal()\n    }\n    if finished.wait(timeout: .now() + limit) == .timedOut {\n        task.terminate()\n        if finished.wait(timeout: .now() + 3) == .timedOut { kill(task.processIdentifier, SIGKILL) }\n        return nil\n    }\n    return (task.terminationStatus, String(decoding: output, as: UTF8.self))\n}\n\nfunc read(_ url: URL) -> Reading {\n    // Look at a copy, so the reader never touches a protected folder and needs no\n    // permission of its own. On APFS the copy is a clone and costs nothing.\n    let scratch = scratchDir.appendingPathComponent(\"\\(UUID().uuidString).\\(url.pathExtension)\")\n    // Across disks there is no clone, and the copy is real. A huge recording on\n    // another drive is not worth copying just to look at one frame of it.\n    let volumes = [url, scratchDir].map {\n        (try? $0.resourceValues(forKeys: [.volumeIdentifierKey]))?.volumeIdentifier as? NSObject\n    }\n    if volumes[0] != volumes[1],\n       let size = (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize, size > 300_000_000 {\n        return .tooBig\n    }\n    do { try fm.copyItem(at: url, to: scratch) } catch { return .nothing }\n    defer { try? fm.removeItem(at: scratch) }\n\n    let started = Date()\n    // Generous, because a cold model load genuinely can take a minute or more.\n    let args = config.useAppleIntelligence ? [scratch.path] : [\"--no-model\", scratch.path]\n    guard let (status, output) = runReader(args, limit: 150) else { return .timedOut }\n    let seconds = Date().timeIntervalSince(started)\n    if seconds > 20 { log(\"SLOW   that took \\(Int(seconds))s, Apple's models were loading or busy\") }\n\n    let lines = output.split(separator: \"\\n\").map {\n        $0.trimmingCharacters(in: .whitespacesAndNewlines)\n    }\n    guard status == 0, let title = lines.first.map(safeName), title.count >= 3 else { return .nothing }\n    return .named(title, how: lines.count > 1 ? lines[1] : \"text\")\n}\n\n/// A second line of defence behind the reader's own tidying: whatever comes back is\n/// made safe before it can become part of a path.\nfunc safeName(_ s: String) -> String {\n    var t = String(s.unicodeScalars.filter { !CharacterSet.controlCharacters.contains($0) })\n    t = t.replacingOccurrences(of: \"[/:\\\\\\\\]\", with: \" \", options: .regularExpression)\n    t = t.trimmingCharacters(in: CharacterSet(charactersIn: \" .\").union(.whitespaces))\n    while t.utf8.count > 180 { t.removeLast() }\n    return t\n}\n\n// MARK: - the rename pass\n\nvar config = Config()\nvar watchDir = home\nvar sizeSeen: [String: Int] = [:]   // sizes from the last look, so half written files wait\nvar tries: [String: Int] = [:]      // how often a file has been read without success\nvar notBefore: [String: Date] = [:] // when a file that failed is worth another look\nvar deniedLogged = false\nlet maxTries = 3\n\nlet work = DispatchQueue(label: \"com.strider.shotcaller.work\", qos: .utility)\n\n// The folder tells us when it changes, so there is no busy polling. A slow sweep\n// runs underneath it as a backstop, and also catches the screenshot folder being\n// moved in System Settings while Shotcaller is running.\nvar vnode: DispatchSourceFileSystemObject?\n\n// Always called on `work`. Opening the folder blocks for as long as the macOS\n// permission box is unanswered, so it must never run on the main thread.\nfunc watchFolderForChanges() {\n    vnode?.cancel()\n    vnode = nil\n    let fd = open(watchDir.path, O_EVTONLY)\n    guard fd >= 0 else { return }\n    let source = DispatchSource.makeFileSystemObjectSource(\n        fileDescriptor: fd, eventMask: [.write, .rename, .delete], queue: work)\n    source.setEventHandler {\n        // The folder itself was moved or deleted: start again on whatever is there now.\n        if !source.data.intersection([.rename, .delete]).isEmpty {\n            work.asyncAfter(deadline: .now() + 2) { watchFolderForChanges() }\n        }\n        // Only long enough for a burst of events to settle. A file that is still\n        // being written is spotted in the pass itself, and waits there.\n        schedulePass(after: 0.2)\n    }\n    source.setCancelHandler { close(fd) }\n    source.resume()\n    vnode = source\n}\n\n// A burst of folder events becomes one pass, not one pass per event.\nvar passScheduled = false\nfunc schedulePass(after delay: TimeInterval) {\n    guard !passScheduled else { return }\n    passScheduled = true\n    work.asyncAfter(deadline: .now() + delay) {\n        passScheduled = false\n        autoreleasepool { pass() }\n    }\n}\n\nfunc isFresh(_ name: String) -> Bool {\n    let lower = name.lowercased()\n    // macOS writes a hidden file first and then renames it into place.\n    guard !lower.hasPrefix(\".\") else { return false }\n    let ext = (lower as NSString).pathExtension\n    if imageTypes.contains(ext) { return config.prefixes.contains { lower.hasPrefix($0) } }\n    if videoTypes.contains(ext), config.renameRecordings {\n        return config.recordingPrefixes.contains { lower.hasPrefix($0) }\n    }\n    return false\n}\n\n/// True when a picture is plainly all there: a PNG or a JPEG always closes with the\n/// same few bytes. macOS moves a finished screenshot into the folder in one piece, so\n/// this lets it be read at once, without first waiting to see whether it still grows.\nfunc looksFinished(_ url: URL, size: Int) -> Bool {\n    let endings: [String: [UInt8]] = [\n        \"png\": [0x49, 0x45, 0x4E, 0x44, 0xAE, 0x42, 0x60, 0x82],\n        \"jpg\": [0xFF, 0xD9], \"jpeg\": [0xFF, 0xD9]\n    ]\n    guard let ending = endings[url.pathExtension.lowercased()], size > ending.count,\n          let handle = try? FileHandle(forReadingFrom: url) else { return false }\n    defer { try? handle.close() }\n    guard (try? handle.seek(toOffset: UInt64(size - ending.count))) != nil,\n          let tail = try? handle.read(upToCount: ending.count) else { return false }\n    return Array(tail) == ending\n}\n\nfunc pass() {\n    let names: [String]\n    do {\n        names = try fm.contentsOfDirectory(atPath: watchDir.path)\n        if deniedLogged {\n            log(\"ACCESS restored, the folder is readable again\")\n            deniedLogged = false\n        }\n    } catch {\n        // The folder was deleted or moved away in the Finder: make it again, the way\n        // macOS would, rather than blaming permissions.\n        // Only when the folder around it is still there: a folder on a drive that is\n        // unplugged is left for when the drive comes back.\n        let parent = watchDir.deletingLastPathComponent().path\n        if !fm.fileExists(atPath: watchDir.path), fm.fileExists(atPath: parent),\n           (try? fm.createDirectory(at: watchDir, withIntermediateDirectories: false)) != nil {\n            log(\"MISSING \\(watchDir.path) was gone, so it has been made again\")\n            watchFolderForChanges()\n            return\n        }\n        if !fm.fileExists(atPath: watchDir.path) {\n            if !deniedLogged {\n                log(\"MISSING \\(watchDir.path) cannot be found. Is its drive plugged in?\")\n                deniedLogged = true\n            }\n            return\n        }\n        if !deniedLogged {\n            log(\"DENIED cannot read \\(watchDir.path): \\(error.localizedDescription)\")\n            log(\"       Allow Shotcaller under System Settings, Privacy and Security,\")\n            log(\"       Files and Folders, then quit and open Shotcaller again.\")\n            deniedLogged = true\n        }\n        return\n    }\n\n    // Forget files that are gone, so this state never grows without limit.\n    let present = Set(names)\n    sizeSeen = sizeSeen.filter { present.contains($0.key) }\n    tries = tries.filter { present.contains($0.key) }\n    notBefore = notBefore.filter { present.contains($0.key) }\n\n    var lookAgainSoon = false\n    let now = Date()\n\n    for name in names where isFresh(name) {\n        if (tries[name] ?? 0) >= maxTries { continue }\n        if let wait = notBefore[name], wait > now { continue }\n\n        let url = watchDir.appendingPathComponent(name)\n        // Only real files. A link named like a screenshot could point anywhere.\n        guard let attrs = try? fm.attributesOfItem(atPath: url.path),\n              attrs[.type] as? FileAttributeType == .typeRegular,\n              let size = attrs[.size] as? Int, size > 1000 else { continue }\n\n        // A file can land on disk before it is finished being written. macOS itself\n        // writes screenshots out of sight and moves them in whole, but a copied or\n        // synced file arrives a piece at a time. A picture that plainly ends where it\n        // should is read at once. Anything else waits until its size has held steady\n        // across two looks and it has sat untouched for a moment, longer for a recording.\n        let isVideo = videoTypes.contains((name as NSString).pathExtension.lowercased())\n        let modified = attrs[.modificationDate] as? Date ?? now\n        // A date in the future (a synced file from a Mac whose clock runs ahead)\n        // must not keep the file waiting forever.\n        let age = now.timeIntervalSince(modified)\n        let settled = sizeSeen[name] == size && !(age >= 0 && age < (isVideo ? 5 : 2))\n        if !settled, !looksFinished(url, size: size) {\n            sizeSeen[name] = size\n            lookAgainSoon = true\n            continue\n        }\n\n        switch read(url) {\n        case .timedOut:\n            tries[name, default: 0] += 1\n            notBefore[name] = Date().addingTimeInterval(60)\n            let last = tries[name]! >= maxTries\n            log(\"ERROR  ran out of time reading \\(name), \" + (last ? \"giving up on it\" : \"will try again in a minute\"))\n            continue\n        case .nothing:\n            tries[name, default: 0] += 1\n            notBefore[name] = Date().addingTimeInterval(600)\n            if tries[name]! >= maxTries {\n                log(\"SKIP   nothing worth naming it after, left alone:  \\(name)\")\n            } else if tries[name] == 1 {\n                log(\"SKIP   nothing worth naming it after yet, will look again later:  \\(name)\")\n            }\n            continue\n        case .tooBig:\n            tries[name] = maxTries\n            log(\"SKIP   too large to copy from another disk, left alone:  \\(name)\")\n            continue\n        case .named(let title, let how):\n            rename(url, name: name, title: title, how: how, created: attrs[.creationDate] as? Date)\n        }\n        sizeSeen.removeValue(forKey: name)\n    }\n\n    if lookAgainSoon { schedulePass(after: 1.5) }\n}\n\nfunc rename(_ url: URL, name: String, title: String, how: String, created: Date?) {\n    var newName = title\n    if config.keepDate {\n        let day: String\n        if let m = name.range(of: \"[0-9]{4}-[0-9]{2}-[0-9]{2}\", options: .regularExpression) {\n            day = String(name[m])\n        } else {\n            day = dayFormat.string(from: created ?? Date())\n        }\n        newName = \"\\(title) \\(day)\"\n    }\n\n    let ext = (name as NSString).pathExtension\n    // A title such as \"Screenshots app settings\" would give a name that still looks\n    // like a fresh screenshot, and Shotcaller would rename it again, forever.\n    if isFresh(\"\\(newName).\\(ext)\") {\n        log(\"SKIP   its title would look like a new screenshot, left alone:  \\(name)\")\n        tries[name] = maxTries\n        return\n    }\n    var target = watchDir.appendingPathComponent(\"\\(newName).\\(ext)\")\n    var n = 2\n    while fm.fileExists(atPath: target.path), n <= 99 {\n        target = watchDir.appendingPathComponent(\"\\(newName) (\\(n)).\\(ext)\")\n        n += 1\n    }\n\n    do {\n        // Never replaces anything: this fails rather than overwrite an existing file.\n        try fm.moveItem(at: url, to: target)\n        let note = how == \"model\" ? \"\" : \"  (from the text)\"\n        log(\"RENAME \\(name)  ->  \\(target.lastPathComponent)\\(note)\")\n    } catch {\n        log(\"ERROR  could not rename \\(name): \\(error.localizedDescription)\")\n        tries[name] = maxTries\n    }\n}\n\n// MARK: - run\n\ntry? fm.createDirectory(at: supportDir, withIntermediateDirectories: true,\n                        attributes: [.posixPermissions: 0o700])\n// Clear out copies left behind by a Shotcaller that was stopped halfway through a\n// read. Only folders whose process is gone; another running copy keeps its own.\nfor leftover in (try? fm.contentsOfDirectory(atPath: scratchRoot.path)) ?? []\nwhere leftover.hasPrefix(\"com.strider.shotcaller-\") || leftover.hasPrefix(\"shotcaller-\") {\n    // Version 1 left single files named shotcaller-<id> behind.\n    let pid = Int32(leftover.split(separator: \"-\").last ?? \"\") ?? 0\n    if pid <= 0 || kill(pid, 0) != 0 {\n        try? fm.removeItem(at: scratchRoot.appendingPathComponent(leftover))\n    }\n}\ntry? fm.createDirectory(at: scratchDir, withIntermediateDirectories: true,\n                        attributes: [.posixPermissions: 0o700])\n// Older versions left these readable by anyone on the Mac.\nfor file in [logFile, configFile] where fm.fileExists(atPath: file.path) {\n    try? fm.setAttributes([.posixPermissions: 0o600], ofItemAtPath: file.path)\n}\n\nconfig = loadConfig(config)\nwatchDir = screenshotFolder(config)\nlog(\"START  watching \\(watchDir.path)\")\n\n// Reading the folder is what makes macOS show its access box on the first run, and\n// that call blocks until the box is answered. It runs off the main thread so the\n// app is fully awake and logging while it waits, rather than looking frozen.\n// One place, one thread, so at most one permission box can ever be pending.\nwork.async {\n    if !fm.fileExists(atPath: watchDir.path) {\n        try? fm.createDirectory(at: watchDir, withIntermediateDirectories: true)\n    }\n    if (try? fm.contentsOfDirectory(atPath: watchDir.path)) == nil {\n        log(\"WAIT   macOS is asking whether Shotcaller may read that folder. Click Allow.\")\n    }\n    watchFolderForChanges()\n    pass()\n}\n\n// Load Apple's models now, on their own thread, so the first real screenshot of the\n// session is not the one that pays for it.\nlet warmArgs = config.useAppleIntelligence ? [\"--warmup\"] : [\"--warmup\", \"--no-model\"]\nDispatchQueue.global(qos: .utility).async {\n    let began = Date()\n    switch runReader(warmArgs, limit: 300)?.status {\n    case nil: log(\"SLOW   Apple's models are taking a long time to get ready\")\n    case 0: log(\"READY  models ready in \\(Int(Date().timeIntervalSince(began)))s\")\n    default: log(\"ERROR  the reader could not warm up Apple's models\")\n    }\n}\n\nlet sweep = DispatchSource.makeTimerSource(queue: work)\nsweep.schedule(deadline: .now() + 30, repeating: 30.0, leeway: .seconds(5))\nsweep.setEventHandler {\n    autoreleasepool {\n        // Pick up edits to the settings, and a change to where macOS puts\n        // screenshots, without needing a restart.\n        config = loadConfig(config)\n        let current = screenshotFolder(config)\n        if current.path != watchDir.path {\n            log(\"MOVED  now watching \\(current.path)\")\n            watchDir = current\n            sizeSeen.removeAll()\n            tries.removeAll()\n            notBefore.removeAll()\n            watchFolderForChanges()\n        } else if vnode == nil {\n            watchFolderForChanges()\n        }\n        pass()\n    }\n}\nsweep.resume()\n\ndispatchMain()"},{"name":"ShotcallerReader/main.swift","text":"// ShotcallerReader\n//\n// Looks at one screenshot or screen recording and prints a short title for it.\n//\n// Output, when a title was found:\n//   line 1  the title, already safe to use in a filename\n//   line 2  how it was found: \"model\" or \"text\"\n// Prints nothing and exits non-zero when nothing is worth naming a file after,\n// which the watcher treats as \"leave this file alone\".\n//\n// How the title is found:\n//\n// 1. Apple's text recogniser reads every line in the picture, in the languages this\n//    Mac is set to.\n// 2. If Apple Intelligence is on, Apple's on-device language model looks at the\n//    picture itself together with that text, says in a sentence what the whole shot\n//    shows, and then writes a title from that (\"Discord chat about Destiny lore\").\n//    A photo with no words in it is named from the picture alone. The model runs on\n//    this Mac. Shotcaller only ever uses the on-device model, never Apple's cloud one.\n// 3. If the model is off, unavailable, or declines, the biggest line of text wins,\n//    as it always did.\n//\n// This runs as its own short-lived process on purpose. Apple's text recogniser\n// deadlocks when it is called repeatedly inside a long-running process: it parks\n// on a semaphore waiting for the neural engine and never returns. Started fresh for\n// one image and then exiting, it is reliable. Keeping it separate also means a\n// wedged read can never wedge the watcher.\n\nimport Foundation\nimport Vision\nimport AppKit\nimport AVFoundation\n#if canImport(FoundationModels)\nimport FoundationModels\n#endif\n\n// MARK: - reading the text\n\nstruct Line {\n    let text: String\n    let box: CGRect      // normalised, origin at the bottom left, so 1.0 is the top\n    var height: Double { Double(box.height) }\n    var y: Double { Double(box.midY) }\n}\n\n/// The languages to read: the ones this Mac is set to, where the recogniser knows them.\n///\n/// The recogniser can guess the language instead, but the first time it guesses one it\n/// has not met, it spends a minute or two building a model for it, and a screenshot\n/// full of names and jargon makes it guess wrongly often. A fixed list means that\n/// building happens once, during the warm-up, and never while a real shot waits.\nfunc readingLanguages(_ request: VNRecognizeTextRequest) -> [String] {\n    let known = (try? request.supportedRecognitionLanguages()) ?? []\n    var chosen: [String] = []\n    for wanted in Locale.preferredLanguages {\n        // \"en-US\" is known as it stands, \"zh-Hans-CN\" as \"zh-Hans\", \"de-AT\" as \"de-DE\".\n        let language = wanted.split(separator: \"-\").first\n        let match = known.first { $0 == wanted || wanted.hasPrefix($0 + \"-\") }\n            ?? known.first { $0.split(separator: \"-\").first == language }\n        if let match, !chosen.contains(match) { chosen.append(match) }\n    }\n    return chosen.isEmpty ? [\"en-US\"] : Array(chosen.prefix(3))\n}\n\nfunc recognise(_ image: CGImage) -> [Line] {\n    let request = VNRecognizeTextRequest()\n    request.recognitionLevel = .accurate\n    request.usesLanguageCorrection = true\n    request.automaticallyDetectsLanguage = false\n    request.recognitionLanguages = readingLanguages(request)\n    do {\n        try VNImageRequestHandler(cgImage: image, options: [:]).perform([request])\n    } catch {\n        return []\n    }\n    var lines: [Line] = []\n    for observation in request.results ?? [] {\n        guard let best = observation.topCandidates(1).first, best.confidence >= 0.3 else { continue }\n        let text = best.string.trimmingCharacters(in: .whitespacesAndNewlines)\n        if !text.isEmpty { lines.append(Line(text: text, box: observation.boundingBox)) }\n    }\n    return lines\n}\n\n/// The text for the model, trimmed to a budget so it always fits alongside the\n/// picture in the model's small context. The largest text comes first, because that\n/// is where the subject usually is; read top to bottom, a screenshot opens with menu\n/// bars, bookmarks and sidebars, and the real subject can fall past the budget.\n/// Everything else follows in reading order, so a page of same-size text still reads\n/// as it should.\nfunc textForModel(_ lines: [Line], budget: Int) -> String {\n    func readingOrder(_ a: Line, _ b: Line) -> Bool {\n        abs(a.y - b.y) > 0.01 ? a.y > b.y : a.box.minX < b.box.minX\n    }\n    let big = Set(lines.indices.sorted { lines[$0].height > lines[$1].height }.prefix(8))\n    let headings = big.sorted { readingOrder(lines[$0], lines[$1]) }.map { lines[$0] }\n    let rest = lines.indices.filter { !big.contains($0) }.map { lines[$0] }.sorted(by: readingOrder)\n\n    var out = \"\", used = 0\n    func add(_ text: String) -> Bool {\n        let piece = String(text.prefix(120))\n        if used + piece.count + 1 > budget { return false }\n        out += piece + \"\\n\"\n        used += piece.count + 1\n        return true\n    }\n    if !headings.isEmpty {\n        _ = add(\"Largest text:\")\n        for line in headings where !add(line.text) { break }\n    }\n    if !rest.isEmpty, add(\"Other text, top to bottom:\") {\n        for line in rest where !add(line.text) { break }\n    }\n    return out\n}\n\n// MARK: - turning any candidate into a safe, tidy filename\n\n/// Titles that describe nothing. A model sometimes falls back on these.\nlet generic: Set<String> = [\n    \"screenshot\", \"screen shot\", \"screen recording\", \"image\", \"picture\", \"photo\",\n    \"untitled\", \"unknown\", \"none\", \"n/a\", \"na\", \"text\", \"document\", \"app\", \"application\",\n    \"website\", \"web page\", \"webpage\", \"screen\", \"computer screen\", \"window\", \"blank\",\n    \"desktop\", \"user interface\", \"interface\"\n]\n\n/// Makes a title safe and pleasant as a filename, or returns nil if nothing useful\n/// is left. Everything the watcher uses as a name passes through here.\nfunc tidy(_ raw: String) -> String? {\n    var t = raw\n    // Only the first line, and never anything that could not appear in a name.\n    t = t.components(separatedBy: .newlines).first ?? \"\"\n    t = String(String.UnicodeScalarView(t.unicodeScalars.map {\n        CharacterSet.controlCharacters.contains($0) ? \" \" : $0\n    }))\n    // Characters that break filenames on macOS, in the Finder, or elsewhere.\n    t = t.replacingOccurrences(of: \"[/:\\\\\\\\|<>*?\\\"`]\", with: \" \", options: .regularExpression)\n    // Emoji and stray symbols like › or • look bad in the Finder.\n    t = String(t.unicodeScalars.filter {\n        !($0.properties.isEmojiPresentation || ($0.properties.isEmoji && $0.value > 0x2000)\n          || CharacterSet.symbols.contains($0) && $0 != \"&\" && $0 != \"+\" && $0 != \"$\" && $0 != \"%\")\n    })\n    t = t.replacingOccurrences(of: \"\\\\s+\", with: \" \", options: .regularExpression)\n    // A model sometimes opens with the obvious.\n    t = t.replacingOccurrences(\n        of: \"^(a |an |the )?(screenshot|screen shot|screen recording|image|picture)( of| showing| from| with)?[ :,-]+\",\n        with: \"\", options: [.regularExpression, .caseInsensitive])\n    // File extensions read off the screen (\"notes.md\", \"photo.png\") only confuse the\n    // name of a file that has its own.\n    t = t.replacingOccurrences(\n        of: \"\\\\.(png|jpe?g|heic|gif|tiff?|pdf|mov|mp4|md|txt|docx?|xlsx?|pptx?|csv|json|html?|swift|js|ts|py)\\\\b\",\n        with: \"\", options: [.regularExpression, .caseInsensitive])\n    t = t.replacingOccurrences(of: \"\\\\s+\", with: \" \", options: .regularExpression)\n    // Leading dots would hide the file; quotes and dashes at either end look stray.\n    let edges = CharacterSet(charactersIn: \" .,;-–—_'‘’“”()[]{}!\").union(.whitespaces)\n    t = t.trimmingCharacters(in: edges)\n\n    // A whole shouted line reads better in normal case.\n    let letters = t.unicodeScalars.filter { CharacterSet.letters.contains($0) }\n    if letters.count >= 8, t == t.uppercased(), t != t.lowercased() {\n        t = t.lowercased()\n        if let first = t.first { t = first.uppercased() + t.dropFirst() }\n    }\n\n    // At most ten words, never ending on a word that leaves the title hanging. A model\n    // sometimes stops short too (\"Three tweets with\").\n    var words = t.split(separator: \" \").map(String.init)\n    let hanging: Set<String> = [\"a\", \"an\", \"the\", \"of\", \"and\", \"or\", \"for\", \"with\", \"to\",\n                                \"in\", \"on\", \"at\", \"by\", \"about\", \"from\", \"&\", \"+\", \"-\"]\n    words = Array(words.prefix(10))\n    while words.count > 2, let last = words.last, hanging.contains(last.lowercased()) {\n        words.removeLast()\n    }\n    t = words.joined(separator: \" \")\n\n    // Short enough to read in the Finder, cut on a word boundary. The byte limit keeps\n    // room for the date and a counter inside the 255 byte limit on a filename.\n    func tooLong(_ s: String) -> Bool { s.count > 60 || s.utf8.count > 180 }\n    if tooLong(t) {\n        var words = t.split(separator: \" \").map(String.init)\n        while words.count > 1, tooLong(words.joined(separator: \" \")) { words.removeLast() }\n        t = words.joined(separator: \" \")\n        while tooLong(t) { t.removeLast() }\n        t = t.trimmingCharacters(in: edges)\n    }\n\n    guard t.count >= 3, t.rangeOfCharacter(from: .letters) != nil,\n          !generic.contains(t.lowercased()) else { return nil }\n    return t\n}\n\n// MARK: - the old way: the biggest line of text\n\n// Words that are almost always interface furniture rather than the subject of a shot.\nlet chrome: Set<String> = [\n    \"file\", \"edit\", \"view\", \"window\", \"help\", \"format\", \"insert\", \"tools\", \"go\",\n    \"bookmarks\", \"history\", \"develop\", \"safari\", \"chrome\", \"finder\", \"firefox\",\n    \"done\", \"cancel\", \"ok\", \"okay\", \"close\", \"back\", \"next\", \"search\", \"menu\",\n    \"home\", \"settings\", \"more\", \"open\", \"save\", \"share\", \"print\", \"today\",\n    \"yesterday\", \"tomorrow\", \"submit\", \"continue\", \"skip\", \"accept\", \"decline\",\n    \"apple\", \"google\", \"untitled\", \"new\", \"all\", \"none\", \"delete\", \"original\",\n    \"sign\", \"log\", \"in\", \"out\", \"up\", \"and\", \"the\", \"for\", \"with\"\n]\n\nfunc isJunk(_ t: String) -> Bool {\n    if t.count < 4 || t.count > 70 { return true }   // long lines are body text\n    if chrome.contains(t.lowercased()) { return true }\n    // A row of menu titles reaches the recogniser as one line, so \"File Edit View\n    // Window Help\" arrives as a single candidate.\n    let words = t.lowercased().split(separator: \" \").map(String.init)\n    if words.count >= 2 {\n        let furniture = words.filter { chrome.contains($0) }.count\n        if Double(furniture) / Double(words.count) >= 0.6 { return true }\n    }\n    // Prices, clocks, page numbers, battery percentages.\n    if t.range(of: \"^\\\\d{1,2}:\\\\d{2}\", options: .regularExpression) != nil { return true }\n    let letters = t.unicodeScalars.filter { CharacterSet.letters.contains($0) }.count\n    return Double(letters) / Double(t.count) < 0.55\n}\n\nfunc biggestLine(_ lines: [Line]) -> String? {\n    struct Scored { let line: Line; let score: Double }\n    var scored: [Scored] = []\n    for line in lines where !isJunk(line.text) {\n        // Big text wins, because a heading is a heading because it is large.\n        var score = line.height * 100\n        // The menu bar strip: small text along the very top. A big heading that\n        // happens to sit up there is not penalised.\n        if line.y > 0.94, line.height < 0.035 { score *= 0.3 }\n        else if line.y > 0.5 { score *= 1.3 }    // headings live in the upper half\n        scored.append(Scored(line: line, score: score))\n    }\n    scored.sort { $0.score > $1.score }\n    guard let top = scored.first else { return nil }\n\n    // Glue on the runner up only when it looks like the same heading wrapped onto a\n    // second line: close below it, and set in the same size.\n    var title = top.line.text\n    if title.count < 26, scored.count > 1 {\n        let second = scored[1].line\n        let sameSize = second.height > top.line.height * 0.75 && second.height < top.line.height * 1.33\n        let menuBar = second.y > 0.94 && second.height < 0.035\n        if sameSize, !menuBar, abs(top.line.y - second.y) < 0.08 {\n            title = second.y > top.line.y ? second.text + \" \" + title : title + \" \" + second.text\n        }\n    }\n    return tidy(title)\n}\n\n// MARK: - the new way: Apple's on-device model\n\n/// For a model that can only read the text (macOS 26).\nlet instructions = \"\"\"\nYou name screenshot files so that people can find them again months later.\nYou are shown a screenshot and the text that was read from it, largest text first.\nWrite one title of 3 to 7 words that says what the screenshot is about.\nName the app or website only when its name or logo is plainly visible in the \\\nscreenshot or the text. Never guess an app. If you are not sure, leave it out.\nA name in a bookmark bar, a tab or the dock is not the app.\nThen give the specific subject: the topic of the conversation, the headline, the \\\nproduct, the error, the setting or the document.\nPrefer specific names and words that appear in the screenshot over vague ones.\nIgnore menu bars, toolbars, sidebars, ads and other furniture around the main content.\nNever begin with the word screenshot. Never include file names or file extensions.\nDo not add details that are not shown. No quotation marks, no emoji, no full stop.\nExamples of the style wanted:\nChat about weekend hiking plans\nAmazon order shipped confirmation\nQ3 revenue by region spreadsheet\nXcode build error missing module\n\"\"\"\n\n/// For a model that can see the picture (macOS 27). It first says what the whole shot\n/// shows, and only then writes the title. That keeps a small model from naming the\n/// file after whichever line of text stands out: a book title on a spine, the first\n/// item of a list, one advert in a feed.\nlet seeingInstructions = \"\"\"\nYou name screenshot files so that people can find them again months later.\nYou are shown a screenshot and the text read from it.\nFirst say in one sentence what the screenshot shows as a whole. Then write a title \\\nof 2 to 7 words.\nLook at the picture first. The text only helps.\nA good title says what the thing is and what it is about.\nIf the picture is mainly a photo of objects, name the objects plainly, and how many \\\nif there are a few. Text printed on them, such as book spines, labels or packaging, \\\nis not the subject.\nIf it shows a home page or feed full of posts, name the app and the page, not one \\\npost or ad on it.\nIf it is a list, name the whole list, not its first item.\nIf it is a chat or conversation, name the app and what the chat is about.\nIgnore ads, menu bars, toolbars, sidebars, bookmarks, the dock and other furniture.\nName an app or website only when its name is written on screen or its logo is \\\nplainly visible. Never guess one from how the screen looks.\nUse specific names from the screenshot where they help. Never invent a category, \\\nshape, topic or detail that is not shown.\nNever begin with the word screenshot. No file names, quotation marks, emoji or full stop.\nExamples of good titles:\nChat about weekend hiking plans\nAmazon order confirmation for headphones\nBlue ceramic mug and saucer\nYouTube home page\nWeekly chores checklist\nXcode build error missing module\n\"\"\"\n\n/// Apps and sites a model tends to name from how a screen looks, rather than from\n/// anything written on it.\nlet knownApps: [String] = [\n    \"notion\", \"todoist\", \"canva\", \"tiktok\", \"discord\", \"slack\", \"reddit\", \"youtube\",\n    \"twitter\", \"instagram\", \"facebook\", \"threads\", \"mastodon\", \"bluesky\", \"linkedin\",\n    \"whatsapp\", \"telegram\", \"signal\", \"gmail\", \"outlook\", \"safari\", \"chrome\", \"firefox\",\n    \"figma\", \"trello\", \"asana\", \"evernote\", \"goodnotes\", \"habitica\", \"steam\", \"spotify\",\n    \"netflix\", \"amazon\", \"microsoft\", \"google\", \"apple notes\", \"obsidian\", \"dropbox\",\n    \"github\", \"chatgpt\", \"claude\", \"codex\", \"cursor\", \"vs code\", \"xcode\", \"terminal\",\n    \"photoshop\", \"excel\", \"word\", \"powerpoint\", \"keynote\", \"pages\", \"numbers\", \"zoom\",\n    \"teams\", \"wikipedia\", \"twitch\", \"pinterest\", \"tumblr\", \"medium\", \"substack\", \"etsy\",\n    \"ebay\", \"libreoffice\", \"daydream\", \"wanderlog\", \"todo\", \"to do\", \"things\", \"bear\", \"craft\",\n    \"messenger\", \"imessage\", \"snapchat\", \"tinder\", \"uber\", \"airbnb\", \"doordash\"\n]\n\n/// A capitalised name in a title that appears nowhere on screen is a guess, such as\n/// \"Todoist tasks\" for a to-do list in some other app. It is dropped when it is a\n/// well-known app, or not an ordinary word at all. Names read off the screen stay.\n@MainActor\nfunc dropGuessedNames(_ title: String, _ lines: [Line]) -> String {\n    let seen = lines.map(\\.text).joined(separator: \" \").lowercased()\n    func onScreen(_ word: String) -> Bool {\n        seen.range(of: \"\\\\b\" + NSRegularExpression.escapedPattern(for: word.lowercased()),\n                   options: .regularExpression) != nil\n    }\n    var t = title\n    for app in knownApps {\n        guard let r = t.range(of: \"\\\\b\\(app)('s)?\\\\b\", options: [.regularExpression, .caseInsensitive]),\n              t[r].first?.isUppercase == true,   // lower case \"word\" or \"pages\" is English\n              !onScreen(app) else { continue }\n        t.removeSubrange(r)\n    }\n    let checker = NSSpellChecker.shared\n    var words = t.split(separator: \" \").map(String.init)\n    words.removeAll { word in\n        var core = word.trimmingCharacters(in: .punctuationCharacters)\n        if core.hasSuffix(\"'s\") || core.hasSuffix(\"’s\") { core = String(core.dropLast(2)) }\n        guard let first = core.unicodeScalars.first, CharacterSet.uppercaseLetters.contains(first),\n              core.count >= 3, core.unicodeScalars.allSatisfy(CharacterSet.letters.contains),\n              !onScreen(core) else { return false }\n        return checker.checkSpelling(of: core, startingAt: 0).location != NSNotFound\n    }\n    t = words.joined(separator: \" \").trimmingCharacters(in: CharacterSet(charactersIn: \" :,-\"))\n    if t != title, let first = t.first { t = first.uppercased() + t.dropFirst() }\n    return t\n}\n\n/// A picture with next to nothing in it: one colour, or very nearly.\nfunc looksBlank(_ image: CGImage) -> Bool {\n    let side = 32\n    var pixels = [UInt8](repeating: 0, count: side * side)\n    let drawn: Bool = pixels.withUnsafeMutableBytes { buffer in\n        guard let context = CGContext(data: buffer.baseAddress, width: side, height: side,\n                                      bitsPerComponent: 8, bytesPerRow: side,\n                                      space: CGColorSpaceCreateDeviceGray(),\n                                      bitmapInfo: CGImageAlphaInfo.none.rawValue) else { return false }\n        context.interpolationQuality = .medium\n        context.draw(image, in: CGRect(x: 0, y: 0, width: side, height: side))\n        return true\n    }\n    guard drawn else { return false }\n    let values = pixels.map(Double.init)\n    let mean = values.reduce(0, +) / Double(values.count)\n    let spread = (values.map { ($0 - mean) * ($0 - mean) }.reduce(0, +) / Double(values.count)).squareRoot()\n    return spread < 6\n}\n\n#if canImport(FoundationModels)\n@available(macOS 26.0, *)\n@Generable\nstruct Named {\n    @Guide(description: \"A 3 to 7 word title saying what the screenshot is about\")\n    var title: String\n}\n\n@available(macOS 26.0, *)\n@Generable\nstruct Described {\n    @Guide(description: \"One sentence saying what the screenshot shows as a whole: what kind of thing it is, and what it is about\")\n    var summary: String\n    @Guide(description: \"A 3 to 7 word title for the file, built from the summary\")\n    var title: String\n}\n\nenum Verdict { case tooLong, declined, transient }\n\n/// Sorts a model error by what to do about it, by its type rather than its wording.\n@available(macOS 26.0, *)\nfunc verdict(on error: Error) -> Verdict {\n    if let e = error as? LanguageModelSession.GenerationError {\n        switch e {\n        case .exceededContextWindowSize: return .tooLong\n        case .guardrailViolation, .refusal, .unsupportedLanguageOrLocale: return .declined\n        default: return .transient\n        }\n    }\n    #if compiler(>=6.4)\n    if #available(macOS 27.0, *), let e = error as? LanguageModelError {\n        switch e {\n        case .contextSizeExceeded: return .tooLong\n        case .guardrailViolation, .refusal, .unsupportedLanguageOrLocale: return .declined\n        default: return .transient\n        }\n    }\n    #endif\n    return .transient\n}\n\n@available(macOS 26.0, *)\nfunc modelTitle(_ image: CGImage?, _ lines: [Line]) async -> String? {\n    let model = SystemLanguageModel.default   // on-device, never the cloud model\n    guard model.isAvailable else { return nil }\n    let hasWords = lines.contains {\n        $0.text.unicodeScalars.filter(CharacterSet.letters.contains).count >= 3\n    }\n    // The picture itself goes to the model only where the model can see (macOS 27).\n    var seen: CGImage?\n    #if compiler(>=6.4)\n    if #available(macOS 27.0, *), model.capabilities.contains(.vision) { seen = image }\n    #endif\n    // With no words in it, a shot can only be named from the picture. A model that\n    // cannot see has nothing to go on, and one that can will still call a blank\n    // square something. Such a file is left alone.\n    if !hasWords {\n        guard let seen, !looksBlank(seen) else { return nil }\n    }\n\n    // The context is small, so if the text plus the picture does not fit, try again\n    // with less text. The model service also fails now and then for no lasting\n    // reason, usually while it is busy loading, so those errors get two more tries.\n    var budgets = [1500, 600, 150]\n    var retries = 2\n    while let budget = budgets.first {\n        let text = hasWords ? textForModel(lines, budget: budget) : \"\"\n        do {\n            #if compiler(>=6.4)\n            if #available(macOS 27.0, *), let seen {\n                let session = LanguageModelSession(model: model, instructions: seeingInstructions)\n                // Room for the sentence that comes before the title.\n                let options = GenerationOptions(samplingMode: .greedy, maximumResponseTokens: 120)\n                let reply: LanguageModelSession.Response<Described>\n                if text.isEmpty {\n                    reply = try await session.respond(generating: Described.self, options: options) {\n                        \"The screenshot:\"\n                        Attachment(seen)\n                        \"No text could be read from it.\"\n                    }\n                } else {\n                    reply = try await session.respond(generating: Described.self, options: options) {\n                        \"The screenshot:\"\n                        Attachment(seen)\n                        \"Text read from the screenshot, which may include ads, menus and words printed on objects:\"\n                        text\n                    }\n                }\n                // Nothing to name when the model itself finds the picture empty.\n                if !hasWords, reply.content.summary.range(\n                    of: \"\\\\b(blank|empty)\\\\b\", options: [.regularExpression, .caseInsensitive]) != nil {\n                    return nil\n                }\n                return tidy(await dropGuessedNames(reply.content.title, lines))\n            }\n            #endif\n            guard !text.isEmpty else { return nil }\n            let session = LanguageModelSession(model: model, instructions: instructions)\n            let options = GenerationOptions(samplingMode: .greedy, maximumResponseTokens: 40)\n            let reply = try await session.respond(\n                to: \"Text read from the screenshot:\\n\\(text)\",\n                generating: Named.self, options: options)\n            return tidy(reply.content.title)\n        } catch {\n            FileHandle.standardError.write(Data(\"model: \\(error)\\n\".prefix(400).utf8))\n            switch verdict(on: error) {\n            case .tooLong:\n                budgets.removeFirst()\n            case .declined:\n                // Guardrails, refusals, unsupported languages: the text will have to do.\n                return nil\n            case .transient:\n                guard retries > 0 else { return nil }\n                retries -= 1\n                try? await Task.sleep(for: .seconds(3))\n            }\n        }\n    }\n    return nil\n}\n#endif\n\nfunc smartTitle(_ image: CGImage?, _ lines: [Line]) async -> String? {\n    #if canImport(FoundationModels)\n    if #available(macOS 26.0, *) { return await modelTitle(image, lines) }\n    #endif\n    return nil\n}\n\n// MARK: - opening the picture\n\n/// A still from a screen recording, a little way in, when whatever was being shown\n/// is usually on screen.\nfunc frame(ofVideo url: URL) async -> CGImage? {\n    let asset = AVURLAsset(url: url)\n    guard let duration = try? await asset.load(.duration), duration.seconds.isFinite else { return nil }\n    let generator = AVAssetImageGenerator(asset: asset)\n    generator.appliesPreferredTrackTransform = true\n    generator.maximumSize = CGSize(width: 3000, height: 3000)\n    let at = CMTime(seconds: min(max(duration.seconds * 0.3, 0), 20), preferredTimescale: 600)\n    return try? await generator.image(at: at).image\n}\n\nfunc load(_ path: String) async -> CGImage? {\n    let url = URL(fileURLWithPath: path)\n    if [\"mov\", \"mp4\"].contains(url.pathExtension.lowercased()) {\n        return await frame(ofVideo: url)\n    }\n    guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return nil }\n    // Very large shots are shrunk while they are decoded, never decoded in full first,\n    // so a small file that claims enormous dimensions cannot eat the memory. The model\n    // sees a few hundred pixels anyway, and the text recogniser is just as accurate\n    // and much quicker at this size.\n    let options: [CFString: Any] = [\n        kCGImageSourceCreateThumbnailFromImageAlways: true,\n        kCGImageSourceCreateThumbnailWithTransform: true,\n        kCGImageSourceThumbnailMaxPixelSize: 3000,\n        kCGImageSourceShouldCacheImmediately: true\n    ]\n    return CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary)\n}\n\n// MARK: - run\n\n// The first read after an install or a macOS update spends a minute or more building\n// Apple's text models for this Mac, and the first after a login loads them. Every one\n// after that is quick. With --warmup the reader pays that cost on a throwaway image,\n// so a real screenshot never waits for it.\n\nlet args = Array(CommandLine.arguments.dropFirst())\nlet useModel = !args.contains(\"--no-model\")\nlet files = args.filter { !$0.hasPrefix(\"--\") }\n\nif args.contains(\"--warmup\") {\n    let size = NSSize(width: 400, height: 120)\n    let canvas = NSImage(size: size)\n    canvas.lockFocus()\n    NSColor.white.setFill()\n    NSRect(origin: .zero, size: size).fill()\n    \"warming up\".draw(at: NSPoint(x: 20, y: 40), withAttributes: [\n        .font: NSFont.systemFont(ofSize: 36), .foregroundColor: NSColor.black\n    ])\n    canvas.unlockFocus()\n    if let cg = canvas.cgImage(forProposedRect: nil, context: nil, hints: nil) {\n        let lines = recognise(cg)\n        if useModel { _ = await smartTitle(cg, lines) }\n    }\n    exit(0)\n}\n\nguard let path = files.first else {\n    FileHandle.standardError.write(Data(\"usage: ShotcallerReader [--no-model] <image or video> | --warmup\\n\".utf8))\n    exit(2)\n}\nguard let image = await load(path) else { exit(3) }\nlet lines = recognise(image)\n\nif useModel, let title = await smartTitle(image, lines) {\n    print(title)\n    print(\"model\")\n    exit(0)\n}\nif let title = biggestLine(lines) {\n    print(title)\n    print(\"text\")\n    exit(0)\n}\nexit(5)"}];
